package com.termux.app.workspace;
import android.app.*;import android.graphics.Rect;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspacePopoverTest {
 Activity a;WorkspacePopover menu;
 @Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().visible().get();}
 @After public void close(){if(menu!=null)menu.dismiss();a.finish();}
 private View anchor(int y){View v=new View(a){@Override public void getWindowVisibleDisplayFrame(Rect out){out.set(0,24,360,420);}@Override public void getLocationOnScreen(int[] xy){xy[0]=12;xy[1]=y;}};a.setContentView(v);return v;}
 private PopupWindow popup()throws Exception{java.lang.reflect.Field f=WorkspacePopover.class.getDeclaredField("window");f.setAccessible(true);return (PopupWindow)f.get(menu);}
 @Test public void constrainedMenuScrollsAboveAnchorAndSelectionRunsOnlyOnce()throws Exception{AtomicInteger selected=new AtomicInteger(),dismissed=new AtomicInteger();menu=new WorkspacePopover(a);for(String label:new String[]{"Фото из галереи","Файл с устройства","Файлы проекта","Файлы окружений"})menu.item(label,com.termux.R.drawable.workspace_folder,selected::incrementAndGet);menu.dismissed(dismissed::incrementAndGet);menu.show(anchor(150));PopupWindow window=popup();assertTrue(menu.isShowing());assertEquals(0,selected.get());assertTrue(window.getHeight()<=150-24-WorkspaceDialogs.dp(a,14));assertEquals(PopupWindow.INPUT_METHOD_NOT_NEEDED,window.getInputMethodMode());assertEquals(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING|WindowManager.LayoutParams.SOFT_INPUT_STATE_UNCHANGED,window.getSoftInputMode());ScrollView scroll=(ScrollView)window.getContentView();LinearLayout items=(LinearLayout)scroll.getChildAt(0);assertEquals(4,items.getChildCount());for(int i=0;i<4;i++)assertNotNull(((TextView)items.getChildAt(i)).getCompoundDrawables()[0]);items.getChildAt(3).performClick();assertEquals(1,selected.get());assertEquals(1,dismissed.get());assertFalse(menu.isShowing());}
 @Test public void belowMenuRetainsItsOwnCallbacksWithoutAutomaticMutation()throws Exception{AtomicInteger selected=new AtomicInteger();menu=new WorkspacePopover(a);menu.item("Save",com.termux.R.drawable.workspace_save,selected::incrementAndGet);menu.item("Close",com.termux.R.drawable.workspace_delete,()->selected.addAndGet(10));menu.showBelow(anchor(70));assertTrue(menu.isShowing());assertEquals(0,selected.get());LinearLayout items=(LinearLayout)((ScrollView)popup().getContentView()).getChildAt(0);items.getChildAt(0).performClick();assertEquals(1,selected.get());assertFalse(menu.isShowing());}
 @Test public void noSpaceAndDismissDoNotRunActionsAndAllowReopen(){AtomicInteger selected=new AtomicInteger(),dismissed=new AtomicInteger();menu=new WorkspacePopover(a);menu.item("File",0,selected::incrementAndGet);menu.dismissed(dismissed::incrementAndGet);menu.show(anchor(24));assertFalse(menu.isShowing());assertEquals(1,dismissed.get());menu.show(anchor(400));assertTrue(menu.isShowing());menu.dismiss();assertEquals(2,dismissed.get());assertEquals(0,selected.get());menu.show(anchor(400));assertTrue(menu.isShowing());menu.dismiss();assertEquals(3,dismissed.get());}
 @Test public void animatedPopoverHasAnchorPivotAndReleasesTouchImmediatelyOnClose()throws Exception{AtomicInteger actions=new AtomicInteger(),dismissals=new AtomicInteger();menu=new WorkspacePopover(a).animated();menu.item("Save",0,actions::incrementAndGet);menu.dismissed(dismissals::incrementAndGet);menu.showBelow(anchor(70));PopupWindow window=popup();View content=window.getContentView();assertEquals(0,content.getAlpha(),.001);assertEquals(.97f,content.getScaleX(),.001);assertEquals(0,content.getPivotY(),.001);LinearLayout items=(LinearLayout)((ScrollView)content).getChildAt(0);View button=items.getChildAt(0);button.performClick();button.performClick();assertEquals(1,actions.get());assertFalse(window.isTouchable());menu.dismissImmediately();assertFalse(menu.isShowing());assertEquals(1,dismissals.get());button.performClick();assertEquals(1,actions.get());menu.showBelow(anchor(70));assertTrue(window.isTouchable());assertTrue(menu.isShowing());menu.dismissImmediately();}
 @Test public void risingMenuRevealsRowsInOrderAndCancelsWithoutGhostTouches()throws Exception{
  menu=new WorkspacePopover(a).rise();AtomicInteger calls=new AtomicInteger();for(int i=0;i<4;i++)menu.item("Row "+i,com.termux.R.drawable.workspace_image_frame,calls::incrementAndGet);menu.show(anchor(400));
  PopupWindow window=popup();View panel=window.getContentView();LinearLayout rows=(LinearLayout)((ScrollView)panel).getChildAt(0);
  java.lang.reflect.Field field=WorkspacePopover.class.getDeclaredField("riseAnimation");field.setAccessible(true);android.animation.ValueAnimator animation=(android.animation.ValueAnimator)field.get(menu);
  assertNotNull(animation);assertEquals(0,rows.getChildAt(3).getAlpha(),.001);animation.setCurrentPlayTime(50);
  assertTrue(panel.getTranslationY()>0);assertTrue(rows.getChildAt(0).getAlpha()>rows.getChildAt(1).getAlpha());assertEquals(0,rows.getChildAt(2).getAlpha(),.001);
  animation.setCurrentPlayTime(120);assertTrue(rows.getChildAt(2).getAlpha()>rows.getChildAt(3).getAlpha());assertTrue(rows.getChildAt(3).getAlpha()>0);
  animation.end();assertEquals(1,panel.getAlpha(),.001);assertEquals(0,panel.getTranslationY(),.001);for(int i=0;i<4;i++)assertEquals(1,rows.getChildAt(i).getAlpha(),.001);
  menu.dismiss();assertFalse(window.isTouchable());menu.dismissImmediately();assertFalse(menu.isShowing());assertNull(field.get(menu));
  menu.show(anchor(400));assertEquals(0,rows.getChildAt(3).getAlpha(),.001);rows.getChildAt(0).performClick();rows.getChildAt(0).performClick();assertEquals(1,calls.get());menu.dismissImmediately();
 }
 @Test public void disabledAnimationsRevealAllRowsImmediately()throws Exception{
  java.lang.reflect.Method scale=android.animation.ValueAnimator.class.getDeclaredMethod("setDurationScale",float.class);scale.setAccessible(true);scale.invoke(null,0f);
  try{menu=new WorkspacePopover(a).rise();menu.item("Photo",com.termux.R.drawable.workspace_image_frame,()->{});menu.show(anchor(400));View panel=popup().getContentView();assertEquals(1,panel.getAlpha(),.001);assertEquals(0,panel.getTranslationY(),.001);assertEquals(1,((LinearLayout)((ScrollView)panel).getChildAt(0)).getChildAt(0).getAlpha(),.001);menu.dismiss();assertFalse(menu.isShowing());}finally{scale.invoke(null,1f);}
 }

 @Test public void attachmentRowsKeepReducedMetricsAndScrollWithinKeyboardSpace()throws Exception{
  menu=new WorkspacePopover(a).largeItems().rise();for(int i=0;i<4;i++)menu.item("Файлы окружений с длинной подписью",com.termux.R.drawable.workspace_image_frame,()->{});menu.show(anchor(150));PopupWindow w=popup();assertTrue(w.getWidth()<=360-WorkspaceDialogs.dp(a,16));assertTrue(w.getHeight()<=150-24-WorkspaceDialogs.dp(a,14));ScrollView panel=(ScrollView)w.getContentView();LinearLayout rows=(LinearLayout)panel.getChildAt(0);assertEquals(4,rows.getChildCount());for(int i=0;i<4;i++){TextView row=(TextView)rows.getChildAt(i);assertEquals(20f,row.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity,.001);assertEquals(WorkspaceDialogs.dp(a,59),row.getMinHeight());assertEquals(WorkspaceDialogs.dp(a,24),row.getCompoundDrawables()[0].getBounds().width());assertEquals(WorkspaceDialogs.dp(a,12),row.getPaddingTop());assertTrue(row.isClickable());}menu.dismissImmediately();
 }

 @Test public void languageDropdownOpensBelowAndDoesNotSelectUntilClick()throws Exception{
  AtomicInteger selected=new AtomicInteger();menu=new WorkspacePopover(a).animated();menu.item("System",0,selected::incrementAndGet);menu.item("Русский",0,selected::incrementAndGet);menu.item("English",0,selected::incrementAndGet);View v=anchor(70);v.setLayoutParams(new FrameLayout.LayoutParams(100,44));Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();menu.showDropdown(v);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(menu.isShowing());View content=popup().getContentView();assertEquals(0,content.getPivotY(),.001);assertEquals(0,selected.get());assertTrue(popup().getHeight()<=420-70-v.getHeight()-WorkspaceDialogs.dp(a,14));((LinearLayout)((ScrollView)content).getChildAt(0)).getChildAt(1).performClick();assertEquals(1,selected.get());menu.dismissImmediately();
 }
}
